import fs from 'node:fs';import path from 'node:path';import{spawnSync}from'node:child_process';import{createHash}from'node:crypto';import{fileURLToPath}from'node:url';
const dir=path.dirname(fileURLToPath(import.meta.url));const[id,command,...args]=process.argv.slice(2);
if(!/^[a-z0-9-]+$/.test(id)||!command||fs.existsSync(path.join(dir,id+'.json')))throw Error('invalid/duplicate run');
const start=new Date();const r=spawnSync(command,args,{cwd:'<repo>',encoding:'utf8',timeout:180000,maxBuffer:32*1024*1024});
const streams={stdout:r.stdout??'',stderr:r.stderr??''};const hashes={};for(const[name,text]of Object.entries(streams)){fs.writeFileSync(path.join(dir,id+'.'+name),text);hashes[name]=createHash('sha256').update(text).digest('hex');}
const m={id,command,args,start:start.toISOString(),end:new Date().toISOString(),elapsedMs:Date.now()-start.getTime(),exit:r.status,signal:r.signal,error:r.error?.code??null,hashes};
fs.writeFileSync(path.join(dir,id+'.json'),JSON.stringify(m,null,2)+'\n');console.log(JSON.stringify(m));console.log(streams.stdout.slice(-1800));console.log(streams.stderr.slice(-600));process.exitCode=r.status??1;

