import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import{createHash}from'node:crypto';import{execFileSync}from'node:child_process';
const root='<repo>',temp='<run-temp>';
const output=root+'/docs/release-artifacts/v4.1.1/manifest-write-boundary/result.json';
const hash=b=>createHash('sha256').update(b).digest('hex');const clean=s=>s.replaceAll(root,'<repo>').replaceAll(temp,'<run-temp>').replace(/\/(?:private\/)?var\/folders\/[^\s'"\n]+/g,'<os-temp>').replace(/[\t ]+$/gm,'');
const files=fs.readdirSync(temp).sort();for(const n of files)assert(fs.lstatSync(path.join(temp,n)).isFile());
const capture=name=>{const b=fs.readFileSync(path.join(temp,name)),text=clean(b.toString());return{name,text,rawSha256:hash(b),preservedSha256:hash(text),rawBytes:b.length,preservedBytes:Buffer.byteLength(text)};};
const commands=files.filter(n=>n.endsWith('.json')).map(name=>{const m=JSON.parse(fs.readFileSync(path.join(temp,name)));assert.equal(name,m.id+'.json');const streams={};for(const key of['stdout','stderr']){streams[key]=capture(m.id+'.'+key);assert.equal(streams[key].rawSha256,m.hashes[key]);}assert.equal(m.exit,m.id==='split-red'?1:0,m.id);assert.equal(m.error,null);assert.equal(m.signal,null);return{...JSON.parse(clean(JSON.stringify(m))),streams};}).sort((a,b)=>a.start.localeCompare(b.start));
for(const id of['cost-probe','split-red','split-tests','focused-final','reviewed-refresh','implementation-fixed','inventory','coverage','script-inventory','docs-links','diff-check'])assert(commands.some(c=>c.id===id),id);
const utilities=files.filter(n=>n.endsWith('.mjs')).map(capture);assert.deepEqual(files,[...commands.flatMap(c=>[c.id+'.json',c.id+'.stdout',c.id+'.stderr']),...utilities.map(u=>u.name)].sort());
const paths=['docs/project-feature-test-inventory.md','docs/stream-verification.md','scripts/internal/feature_implementation_manifest_lib.mjs','scripts/internal/verify_feature_implementation_evidence.mjs','scripts/internal/feature_manifest_refresh_boundary.test.mjs','scripts/internal/feature_manifest_validation.test.mjs','test/fixtures/project_feature_implementation_evidence.json'];
const prior=JSON.parse(fs.readFileSync(output,'utf8'));assert(!prior.followup);const initialHash=hash(JSON.stringify(prior));
const probe=commands.find(c=>c.id==='cost-probe').streams.stdout.text.trim().split('\n').map(s=>JSON.parse(s));
prior.followup={scope:'생성 CLI의 승인 보존 경계와 검증 반복 비용 보완. 이번 도구 범위 마감이며 V411-04 전체 또는 릴리즈 완료 아님',baseCommit:execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(),recordedAt:new Date().toISOString(),initialRecordCanonicalSha256:initialHash,
 sourceHashes:Object.fromEntries(paths.map(p=>[p,hash(fs.readFileSync(root+'/'+p))])),commands,utilities,
 diagnosis:{observed:probe,readBytesMeaning:'실제 fs.readFileSync 반환값의 누적 바이트. 물리 디스크 I/O량 또는 저장량이 아님',finding:'정상 986개 검사 뒤 각 내장 반례가 변경되지 않은 전체 986개를 반복 검사. 정상 및 missing-id 반례가 각각 약 48초/51만 회 읽기를 소비. 같은 180초 상한에서 중복 제거 뒤 전체 15개 반례가 완료됨',notClaimed:'과거 시간초과 당시 정확히 어느 반례였는지는 기록이 없어 단정하지 않음'},
 preservation:{checks:'기존 집합/개별 항목 검사 문장을 분리하여 재사용. 정상 전체 986개·독립 승인 전수 검사 유지. 내장 반례 15개와 각 예상 오류 그대로 유지',copyOnWrite:'정상 입력 재귀 동결. 변경 항목은 clone으로만 전달. 집합 검사는 매번 전수. 정상 입력 실패 뒤 반례는 미실행·전체 exit 실패',approvals:'기존 REVIEW4 audit/approval 검증 후 inventorySha256만 갱신. 새 승인 또는 과거 PASS 복사 없음',sourceChanges:'제품 소스·API/schema/미디어/저장 로직 변경 없음',diagnosticOrder:'집합 오류를 항목 오류보다 먼저 나열. 진단 문구·FAIL 조건 유지',historicalDocs:'backlog와 중앙 과거 실행 기록의 옛 refresh 명령은 당시 이력으로 유지. 현행 inventory 안내만 변경'},
 results:{focusedTests:9,implementationFeatureRows:986,implementationNegativeFixtures:15,implementationElapsedMs:commands.find(c=>c.id==='implementation-fixed').elapsedMs},
 failures:[{id:'split-red',expected:true,reason:'분리 집합 검사 함수 미구현',resolvedBy:'focused-final'},{previousRun:'implementation-evidence',reason:'180초 상한 도달',resolvedBy:'implementation-fixed',timeoutChanged:false},{previousRun:'focused',reason:'미등록 옵션 exit 기대값 1/2 불일치',resolvedBy:'focused-final'}],
 notRun:['제품 build/Auth/media/녹화·실제 UI/30분/120분','나머지 v400 정책 검사와 전체 문서 정리','push/PR/merge/tag/Release'],
 cleanup:{status:'pending',serverOrPortStarted:false,files:files.map(name=>({name,bytes:fs.statSync(path.join(temp,name)).size,sha256:hash(fs.readFileSync(path.join(temp,name)))}))},
 tokenUsage:{consumed:null,reason:'실행 묶음별 독립 집계 없음. 실제 elapsed는 명령별 보존'},
 next:'남은 v400 실제 정책/회귀 검사에서 과거 문구 의존 분리 → 나머지 문서 소비자·기록 생성/보존 정리 → README 우선 전체 문서 정리',
};
const text=JSON.stringify(prior,null,2)+'\n';for(const parts of[['','Users',''],['','private','tmp',''],['','private','var','folders','']])assert(!text.includes(parts.join('/')),'로컬 경로 잔여');
fs.writeFileSync(output,text);const saved=JSON.parse(fs.readFileSync(output));const initial={...saved};delete initial.followup;assert.equal(hash(JSON.stringify(initial)),initialHash);
console.log(JSON.stringify({commands:commands.length,utilities:utilities.length,resultBytes:Buffer.byteLength(text),initialRecordUnchanged:true}));

// 정상 986행 검증과 기존 missing-id 반례 1개의 비용 구분. 전체 suite 판정이 아니다.
import fs from 'node:fs';import assert from 'node:assert/strict';import{performance}from'node:perf_hooks';
import{createHash}from'node:crypto';
import{loadImplementationManifest,parseFeatureRows,validateImplementationManifest}from'<repo>/scripts/internal/feature_implementation_manifest_lib.mjs';
import{validateReview4AppliedManifest}from'<repo>/scripts/internal/feature_semantic_evidence_lib.mjs';
const rootDir='<repo>';
const paths=['docs/project-feature-test-inventory.md','test/fixtures/project_feature_implementation_evidence.json'];
const hash=b=>createHash('sha256').update(b).digest('hex');const before=paths.map(p=>hash(fs.readFileSync(rootDir+'/'+p)));
const inventoryText=fs.readFileSync(rootDir+'/'+paths[0],'utf8'),rows=parseFeatureRows(inventoryText),manifest=loadImplementationManifest(rootDir);
const read=fs.readFileSync;let reads=0,bytes=0,readMs=0;
fs.readFileSync=function(...args){const start=performance.now();const result=read.apply(this,args);readMs+=performance.now()-start;reads++;bytes+=Buffer.byteLength(result);return result;};
function measure(name,run){reads=0;bytes=0;readMs=0;const start=performance.now();console.log(JSON.stringify({name,phase:'start'}));const result=run();console.log(JSON.stringify({name,phase:'end',elapsedMs:performance.now()-start,reads,bytes,readMs,...result}));}
try{
  measure('baseline',()=>{const result=validateImplementationManifest({rootDir,inventoryText,rows,manifest});assert.equal(result.ok,true,result.errors.slice(0,4).join(';'));return{errors:result.errors.length,rows:result.summary.manifestRows};});
  measure('review4-global',()=>{const errors=validateReview4AppliedManifest({rows,manifest});assert.equal(errors.length,0,errors.slice(0,4).join(';'));return{errors:errors.length};});
  measure('negative-missing-id',()=>{const copy={...manifest,items:manifest.items.filter(item=>item.id!=='UI-019')};const result=validateImplementationManifest({rootDir,inventoryText,rows,manifest:copy});assert(!result.ok&&result.errors.some(e=>e.includes('manifest missing feature ID UI-019')));return{rejected:true,errors:result.errors.length};});
}finally{fs.readFileSync=read;}
assert.deepEqual(paths.map(p=>hash(fs.readFileSync(rootDir+'/'+p))),before);console.log(JSON.stringify({inputsUnchanged:true,fullSuite:false}));

// 기존 독립 승인 원장을 대조하고 문서 hash 하나만 갱신한다. 승인 생성은 하지 않는다.
import fs from 'node:fs';import assert from 'node:assert/strict';import {isDeepStrictEqual}from'node:util';import{execFileSync}from'node:child_process';
import{parseFeatureRows,writeImplementationManifest}from'<repo>/scripts/internal/feature_implementation_manifest_lib.mjs';
import{applyApprovedReview4SemanticClosure}from'<repo>/scripts/internal/feature_semantic_review4_apply.mjs';
const rootDir='<repo>',p='test/fixtures/project_feature_implementation_evidence.json',inv='docs/project-feature-test-inventory.md';
const read=f=>JSON.parse(fs.readFileSync(rootDir+'/'+f,'utf8'));
const inventoryText=fs.readFileSync(rootDir+'/'+inv,'utf8'),rows=parseFeatureRows(inventoryText);
const oldText=execFileSync('git',['show','HEAD:'+inv],{cwd:rootDir,encoding:'utf8'});
assert.equal(rows.length,986);assert(isDeepStrictEqual(rows,parseFeatureRows(oldText)));
const raw=fs.readFileSync(rootDir+'/'+p,'utf8'),manifest=JSON.parse(raw);
const next=applyApprovedReview4SemanticClosure({rootDir,inventoryText,rows,manifest,
 audit:read('test/fixtures/v390_review4_feature_semantic_source_audit.json'),approvals:read('test/fixtures/v390_review4_feature_semantic_source_approvals.json')});
const keys=Object.keys({...manifest,...next}).filter(k=>k!=='inventorySha256'&&!isDeepStrictEqual(manifest[k],next[k]));assert.equal(keys.length,0,'예상 외 변경: '+keys.join(','));assert.notEqual(next.inventorySha256,manifest.inventorySha256);
const formatted=JSON.stringify(next,null,2)+'\n',expected=raw.replace('"inventorySha256": "'+manifest.inventorySha256+'"','"inventorySha256": "'+next.inventorySha256+'"');assert.equal(formatted===expected,true,'문서 hash 외 바이트 변경');
writeImplementationManifest(rootDir,next);assert(isDeepStrictEqual(read(p),next));fs.writeFileSync(rootDir+'/'+p,formatted);
console.log(JSON.stringify({rows:986,onlyChangedField:'inventorySha256',approvalAndProofUnchanged:true,previous:manifest.inventorySha256,current:next.inventorySha256}));

